package org.sleepwell.app;
import android.content.*;
/** Private current-run budget ledger; portable alarm settings never contain this runtime state. */
final class SnoozeBudgets {
 private static String key(int id,String suffix){return "snoozeBudget_"+id+"_"+suffix;}
 static long spent(Context context,int id,String run){SharedPreferences p=Prefs.of(context);try{if(!run.equals(p.getString(key(id,"owner"),"")))return -1;long spent=p.getLong(key(id,"spent"),-1);return spent>=0&&spent<=300L*60000?spent:-1;}catch(ClassCastException bad){return -1;}}
 static long remaining(Context c,Alarm alarm,String run){if(alarm.snoozeTotalInvalid)return 0;if(alarm.snoozeTotalMinutes==0)return Long.MAX_VALUE;return SnoozeBudget.remaining(alarm.snoozeTotalMinutes,spent(c,alarm.id,run));}
 static boolean started(Context c,Alarm alarm,String run,boolean continuation){synchronized(Scheduler.class){SharedPreferences p=Prefs.of(c);long used=0;if(continuation){SnoozeDelivery.Pending pending=SnoozeDelivery.continuation(c,alarm);if(pending==null)return false;used=pending.spent;}return p.edit().putString(key(alarm.id,"owner"),run).putLong(key(alarm.id,"spent"),used).remove(key(alarm.id,"pending")).remove(key(alarm.id,"snapshot")).commit();}}
 /** Revoke durable delivery authority before touching Android's queued operation. Historical JSON alone is inert. */
 static void cancel(Context c,int id){synchronized(Scheduler.class){if(!Prefs.of(c).edit().remove(key(id,"pending")).remove(key(id,"snapshot")).commit())throw new IllegalStateException("Pending snooze could not be cancelled. Retry before leaving this alarm.");}}
 static Reservation reserve(Context c,Alarm alarm,String run,int count,long from,long until){synchronized(Scheduler.class){if(!AlarmService.current(c,run)||until<=from)throw new IllegalArgumentException("Snooze offer expired. Reopen Snooze.");SharedPreferences p=Prefs.of(c);long oldSpent=spent(c,alarm.id,run);if(oldSpent<0){if(alarm.snoozeTotalMinutes!=0||alarm.snoozeTotalInvalid)throw new IllegalArgumentException("Snooze budget needs a fresh alarm occurrence.");oldSpent=0;}long duration=until-from,remaining=remaining(c,alarm,run);if(duration>remaining)throw new IllegalArgumentException("Only "+SnoozeBudget.label(remaining)+" of snooze time remains.");if(count!=Prefs.number(c,"snoozes_"+alarm.id,0)||!AlarmInputs.canSnooze(true,count,alarm.snoozeLimit))throw new IllegalArgumentException("Snooze offer changed. Reopen Snooze.");long next;try{next=Math.addExact(oldSpent,duration);}catch(ArithmeticException overflow){throw new IllegalArgumentException("Snooze budget is unreadable.");}if(next>300L*60000)throw new IllegalArgumentException("Total snooze duration is outside the supported range.");String snapshot=alarm.json().toString();Reservation reservation=new Reservation(p,alarm.id,run,oldSpent,count,until,p.getString("snoozed_"+alarm.id,null));if(!p.edit().putString(key(alarm.id,"owner"),run).putLong(key(alarm.id,"spent"),next).putLong(key(alarm.id,"pending"),until).putString(key(alarm.id,"snapshot"),snapshot).putString("snoozed_"+alarm.id,snapshot).putInt("snoozes_"+alarm.id,count+1).commit())throw new IllegalStateException("Snooze budget could not be saved. Alarm continues.");return reservation;}}
 static final class Reservation {final SharedPreferences p;final int id,count;final String run,priorSnapshot;final long spent,deadline;Reservation(SharedPreferences p,int id,String run,long spent,int count,long deadline,String prior){this.p=p;this.id=id;this.run=run;this.spent=spent;this.count=count;this.deadline=deadline;priorSnapshot=prior;}boolean rollback(){synchronized(Scheduler.class){if(!run.equals(p.getString(key(id,"owner"),""))||p.getLong(key(id,"pending"),0)!=deadline)return false;SharedPreferences.Editor edit=p.edit().putLong(key(id,"spent"),spent).putInt("snoozes_"+id,count).remove(key(id,"pending")).remove(key(id,"snapshot"));if(priorSnapshot==null)edit.remove("snoozed_"+id);else edit.putString("snoozed_"+id,priorSnapshot);return edit.commit();}}}
 private SnoozeBudgets(){}
}
